import 'server-only'
import { createTransport } from 'nodemailer'
import type { NodemailerConfig } from 'next-auth/providers/nodemailer'

type Params = Parameters<NonNullable<NodemailerConfig['sendVerificationRequest']>>[0]

const escapeHtml = (s: string) =>
  s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!)

/** French, plain + HTML magic-link email. The URL is generated by Auth.js on our own origin and escaped anyway. */
export async function sendMagicLink({ identifier, url, provider }: Params) {
  const transport = createTransport(provider.server)
  const safeUrl = escapeHtml(url)
  const result = await transport.sendMail({
    to: identifier,
    from: provider.from,
    subject: 'Ton lien de connexion Tresser',
    text: `Connecte-toi à Tresser :\n${url}\n\nCe lien expire dans 15 minutes et ne fonctionne qu'une fois.\nSi tu n'as rien demandé, ignore cet e-mail.`,
    html: `<!doctype html><html lang="fr"><body style="font-family:system-ui,sans-serif;background:#faf6f1;padding:24px;color:#2b1d14">
<table role="presentation" width="100%" style="max-width:480px;margin:auto;background:#fff;border-radius:16px;padding:32px">
<tr><td><h1 style="font-size:20px;margin:0 0 16px">Connecte-toi à Tresser</h1>
<p style="margin:0 0 24px">Clique sur le bouton ci-dessous. Le lien expire dans 15 minutes et ne fonctionne qu'une fois.</p>
<p style="margin:0 0 24px"><a href="${safeUrl}" style="display:inline-block;background:#7a3e1d;color:#fff;padding:12px 20px;border-radius:999px;text-decoration:none;font-weight:600">Me connecter</a></p>
<p style="font-size:13px;color:#6b5a4e;margin:0">Si tu n'as rien demandé, ignore simplement cet e-mail.</p></td></tr></table></body></html>`,
  })
  const failed = result.rejected.filter(Boolean)
  if (failed.length) throw new Error('Magic link e-mail could not be delivered')
}
